{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does ATU installation cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ATU installation in Miami-Dade typically costs $12,000-$25,000 depending on system type, capacity, site conditions, and installation complexity. Small residential ATUs cost $12,000-$18,000. Medium ATUs cost $18,000-$25,000. Large ATUs cost $25,000-$35,000. ATUs typically cost $5,000-$10,000 more than conventional systems due to mechanical components."
      }
    },
    {
      "@type": "Question",
      "name": "What is an advanced treatment unit?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Advanced Treatment Units (ATUs) are aerobic wastewater treatment systems that use oxygen to break down septic waste more efficiently than conventional anaerobic septic tanks. ATUs inject air through mechanical blowers to create oxygen-rich environment supporting specialized aerobic bacteria. ATUs produce substantially better wastewater treatment with effluent containing less than 30 mg/L BOD and less than 25 mg/L TSS."
      }
    },
    {
      "@type": "Question",
      "name": "When do you need an ATU instead of conventional septic?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ATUs are needed when site conditions require superior treatment quality including small lot sizes, high groundwater, environmental sensitivity, failed conventional systems, or Miami-Dade County Type 3 or Type 4 requirements. ATUs can work effectively with smaller drainfields making them suitable for limited space properties."
      }
    },
    {
      "@type": "Question",
      "name": "What are the benefits of ATU systems?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ATU benefits include superior wastewater treatment quality, smaller drainfields possible, better groundwater protection, flow management preventing overloading, and meeting Miami-Dade Type 3 or Type 4 standards. Benefits justify higher costs for properties requiring superior treatment."
      }
    },
    {
      "@type": "Question",
      "name": "How do ATU systems work?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ATU systems inject air into wastewater through mechanical blowers creating oxygen-rich environment. Oxygen supports aerobic bacteria growth that digests organic matter more thoroughly. Wastewater enters aeration chamber, bacteria break down waste, solids settle in clarification chamber, some material recirculated for additional treatment, and high-quality effluent discharged to drainfield."
      }
    },
    {
      "@type": "Question",
      "name": "What maintenance do ATUs require?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ATU systems require annual or semi-annual professional maintenance due to mechanical components. Maintenance includes inspection and servicing of blowers and compressors, pump and timer servicing, control system testing, electrical system inspection, effluent quality testing, and operating permit compliance. Maintenance frequency higher than conventional systems but essential for proper function."
      }
    },
    {
      "@type": "Question",
      "name": "What types of ATU systems are available?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Three primary ATU types include suspended-growth systems with bacteria in wastewater, fixed-film systems using porous media for bacterial biofilm, and sequencing batch reactors combining all processes in single chamber. System type selection depends on property needs, space constraints, and treatment requirements."
      }
    }
  ]
}

