{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does lift station installation cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Lift station installation in Miami-Dade typically costs $15,000-$50,000 depending on pump capacity, station type, site conditions, and installation complexity. Small submersible stations cost $15,000-$30,000. Standard stations cost $25,000-$45,000. Large wet well/dry well stations cost $40,000-$75,000. Costs include pumps, controls, electrical systems, construction, and permits."
      }
    },
    {
      "@type": "Question",
      "name": "What is a lift station and when is it needed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Lift stations pump sewage from lower elevations to higher elevations or treatment facilities when gravity flow is not feasible. They are needed for flat topography, low elevation areas, long distances requiring pressure, or properties below sewer main elevation. In Miami-Dade's flat topography, lift stations are essential for wastewater infrastructure."
      }
    },
    {
      "@type": "Question",
      "name": "How do lift stations work?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Wastewater flows into wet well. Pumps activate when wastewater reaches certain level. Pumps push wastewater through force main pipe to higher elevation or treatment facility. Control systems monitor pump operation automatically. Lift stations enable wastewater movement where gravity systems cannot function."
      }
    },
    {
      "@type": "Question",
      "name": "What are Miami-Dade requirements for lift stations?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Miami-Dade requires mandatory prior written approval from county director, compliance with design standards, all wet wells classified as Permit Required Confined Spaces with OSHA compliance, proper ventilation systems, Class I Division 2 electrical classifications, and control panels preferably in separate buildings. Professional engineering and installation required."
      }
    },
    {
      "@type": "Question",
      "name": "Do lift stations require permits?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, all new or replacement installations require mandatory prior written approval from Miami-Dade County director before construction begins. Required documentation includes design plans, pump specifications, electrical schematics, and compliance with design standards. Permit application includes design review and approval process."
      }
    },
    {
      "@type": "Question",
      "name": "How are lift stations maintained?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Lift stations require ongoing maintenance including regular pump inspection and servicing, electrical system testing, confined space safety inspections, ventilation system verification, and preventive maintenance programs. Professional maintenance services ensure proper system function, reliability, and compliance with safety requirements."
      }
    },
    {
      "@type": "Question",
      "name": "What's the difference between submersible and wet well/dry well lift stations?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Submersible lift stations are used for up to 60 horsepower per pump, with pumps installed directly in wet well. Wet well/dry well configurations separate pumping area from sump area, used for pumps exceeding 60 horsepower, allowing larger equipment and better maintenance accessibility. Station type depends on pump capacity requirements."
      }
    }
  ]
}

