{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is a septic tank camera inspection?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Camera inspections use specialized waterproof cameras inserted into septic tanks and drain lines to visually inspect interior conditions without excavation. Cameras travel through pipes transmitting real-time video footage, allowing technicians to see cracks, root intrusion, blockages, and structural damage not visible during surface inspections."
      }
    },
    {
      "@type": "Question",
      "name": "How much does a septic camera inspection cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Camera inspections typically cost $200-$500 in Miami-Dade County. Basic inspections cost $200-$300. Comprehensive inspections including drain field cost $400-$500. Costs vary based on system complexity, inspection scope, and documentation needed."
      }
    },
    {
      "@type": "Question",
      "name": "What can a camera inspection show about my septic tank?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Camera inspections reveal cracks or breaks in pipes, root intrusion, pipe deterioration, blockages, structural damage, loose joints, and overall system condition. Cameras show exact problem locations and causes, providing visual proof needed for accurate repairs and eliminating guesswork."
      }
    },
    {
      "@type": "Question",
      "name": "When do you need a camera inspection vs regular inspection?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Camera inspections are needed when visual inspections don't reveal causes of problems, before major repairs, when diagnosing persistent issues, for property transactions, or when planning drain field work. Regular visual inspections work for routine maintenance, but cameras provide essential diagnostic information when problems need detailed investigation."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a camera inspection take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most camera inspections take 45-90 minutes. Basic inspections take 45-60 minutes. Comprehensive inspections including drain field take 60-90 minutes. Report preparation adds 24-48 hours typically. Camera inspections are efficient compared to traditional diagnostic methods requiring excavation."
      }
    },
    {
      "@type": "Question",
      "name": "Can camera inspections find drain field problems?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, camera inspections identify drain field problems including pipe blockages, root intrusion, pipe deterioration, collapsed pipes, and problems causing drain field failure. Drain field camera inspections help determine whether fields can be repaired or need complete replacement, providing essential information for repair planning."
      }
    },
    {
      "@type": "Question",
      "name": "How often should I get a camera inspection?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Camera inspections are recommended every 5-10 years as part of routine maintenance, or whenever persistent problems occur that visual inspection doesn't explain. Before major repairs or property transactions, camera inspections provide detailed condition assessment. Regular camera inspections catch problems early and prevent expensive failures."
      }
    }
  ]
}

