      }
    },
    {
      "@type": "Question",
      "name": "Can I locate my septic tank myself?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Homeowners can try basic methods like looking for visual clues or following sewer lines, but these provide approximate locations rather than exact boundaries. Professional service uses specialized equipment like GPR and electronic locators that provide precise location, depth measurements, and official documentation."
      }
    },
    {
      "@type": "Question",
      "name": "How do professionals locate septic tanks?",
      "acceptedAnswer": {
