  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does catch basin installation cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Catch basin installation in Miami typically costs $500-$5,000 per basin depending on size, material (plastic vs concrete), installation depth, and connection to drainage systems. Plastic basins cost $200-$500. Concrete basins cost $2,000-$5,000. Installation labor costs $800-$2,800."
      }
    },
    {
      "@type": "Question",
      "name": "What is a catch basin?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Catch basins are rectangular or circular basins that collect surface water and direct it into drainage pipes or channels. They feature grated inlets allowing water flow while preventing larger debris from entering the system and sump areas collecting sediment and pollutants."
      }
    },
    {
      "@type": "Question",
      "name": "How does a catch basin work?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Catch basins work through gravity-based mechanisms where water flows into grated surface openings, is temporarily stored in sump areas where solid particles settle, and cleaner water flows through drainage pipes to larger water management systems preventing flooding."
      }
    },
    {
      "@type": "Question",
      "name": "When do you need a catch basin?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Catch basins needed in low-lying areas collecting stormwater runoff, high-debris environments like parking lots and landscaping zones, areas prone to urban flooding, and zones with significant surface runoff during Miami's heavy tropical rainfall."
      }
    },
    {
      "@type": "Question",
      "name": "How do you install a catch basin?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Installation process includes site assessment identifying low points, excavation to appropriate depth, positioning basin with proper alignment, connecting pipes to drainage systems, securing grated inlet at surface level, testing for proper function, and final inspection."
      }
    },
    {
      "@type": "Question",
      "name": "What maintenance do catch basins need?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Maintenance requirements include regular debris removal from sump areas, cleaning and inspecting grates preventing blockages, professional vacuum truck cleaning removing accumulated pollutants and sediment, and more frequent maintenance during hurricane season."
      }
    },
    {
      "@type": "Question",
      "name": "What's the difference between plastic and concrete catch basins?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Plastic catch basins cost $200-$500, are lightweight and easier to install, suitable for residential applications. Concrete catch basins cost $2,000-$5,000, are more durable for heavy-duty applications, better for commercial use, and have longer lifespan in Miami's environment."
      }
    }
  ]
}

