{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does drain field installation cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Drain field installation in Miami-Dade typically costs $3,000-$15,000 depending on size, soil conditions, and system type. Small drain fields cost $3,000-$6,000. Standard drain fields cost $6,000-$12,000. Large drain fields cost $10,000-$18,000. Elevated systems cost $10,000-$20,000. Professional contractors provide detailed estimates based on specific property needs."
      }
    },
    {
      "@type": "Question",
      "name": "How do you install a drain field?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Installation includes site evaluation, soil percolation testing, drain field design, permit application, site preparation, excavation, gravel bed installation, distribution pipe installation, additional cover, and final inspection. Professional contractors manage entire process ensuring compliance and proper function."
      }
    },
    {
      "@type": "Question",
      "name": "How long does drain field installation take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Installation timeline typically takes 1-2 weeks from permit approval through final inspection. Permit approval takes 4-8 weeks before work begins. Physical installation takes 5-8 days. Final inspection takes 3-5 days. Total timeline from site evaluation to completion typically takes 6-12 weeks including permit approval time."
      }
    },
    {
      "@type": "Question",
      "name": "What is required for drain field installation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Requirements include site evaluation, soil percolation testing, drain field design meeting standards, DERM permit approval, proper elevation (36 inches above high water table), setback compliance, adequate space, and professional installation by licensed contractor. Meeting requirements ensures compliance and proper function."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need permits to install a drain field?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, drain field installation requires prior approval from Miami-Dade DERM before installation begins. Required documentation includes design plans, site evaluation results, soil testing data, and permit application forms. Permit fees cost $1,600-$5,100 typically. Professional contractors handle permit applications."
      }
    },
    {
      "@type": "Question",
      "name": "What type of drain field is best for Miami?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Best type depends on site-specific conditions. Conventional trench systems work well for sites with good soil. Chamber systems provide larger capacity. Mound systems are needed when water table is too high. Drip irrigation systems provide even distribution. Professional contractors evaluate site conditions and recommend appropriate type. Miami's high water table often requires elevated systems."
      }
    },
    {
      "@type": "Question",
      "name": "Why is professional installation important?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Professional installation ensures proper design, correct installation practices, compliance with requirements, environmental protection, long-term reliability, and cost effectiveness. Licensed contractors understand local requirements and provide installation meeting all standards. Professional installation is essential for drain field function."
      }
    }
  ]
}

