  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does drainage system repair cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Drainage system repairs in Miami typically cost $300-$700 for routine maintenance, $500-$2,500 for pipe repairs, $1,000-$5,000 for catch basin repairs, and $2,000-$10,000 for extensive system repairs depending on scope and complexity. Emergency repairs may cost more due to urgency."
      }
    },
    {
      "@type": "Question",
      "name": "What causes drainage system problems?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Blockage and accumulation of sediment and debris are leading causes of flooding in Miami-Dade County, with grass clippings, leaves, debris, and excessive lawn care products blown into stormwater inlets causing system failures. Other causes include corrosion, structural failures, inadequate capacity, and environmental factors."
      }
    },
    {
      "@type": "Question",
      "name": "How do you repair a drainage system?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Repair process includes field inspection, pipe desilting to inspect joints, video inspection where access allows, coordination with drainage and maintenance offices, repair or replacement of damaged components, testing for proper function, and comprehensive documentation. Professional contractors manage entire process."
      }
    },
    {
      "@type": "Question",
      "name": "What are signs drainage needs repair?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Common signs include standing water after rainfall, visible flooding during average rain events, clogged storm drains with visible debris, sinkholes or subsidence around drainage structures, foul odors from drains, foundation water intrusion, and landscape damage from water flow."
      }
    },
    {
      "@type": "Question",
      "name": "Can you repair drainage pipes?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, drainage pipes can be repaired depending on condition and damage extent. Basic pipe repairs cost $500-$2,500. Pipe desilting and cleaning cost $800-$2,000. Pipe section replacement costs $1,500-$5,000. Professional assessment determines if repair or replacement needed."
      }
    },
    {
      "@type": "Question",
      "name": "When does drainage need replacement vs repair?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Repair appropriate when problems localized and fixable, system generally in good condition, and cost-effective repair possible. Replacement needed when extensive corrosion, multiple structural failures, pressure rating requirements exceed 10 psi, or system design inadequate. Professional evaluation determines best approach."
      }
    },
    {
      "@type": "Question",
      "name": "What emergency drainage repair services are available?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Emergency repairs available by calling 311 for immediate flooding reports in Miami-Dade County or contacting municipal Public Works Departments. Miami-Dade County Stormwater Utility addresses flooding. Professional contractors provide emergency repair services for immediate flooding threats."
      }
    }
  ]
}

