{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does French drain installation cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "French drain installation in Miami typically costs $2,670-$3,848 on average, with exterior drains costing $10-$15 per linear foot including all parts and labor. Standard installations cost $1,000-$1,500. Interior drains cost $40-$100 per linear foot. Labor represents 85.7% of total costs."
      }
    },
    {
      "@type": "Question",
      "name": "What is a French drain?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "French drains are perforated pipes placed in trenches that absorb and direct water flow away from areas susceptible to damage. Exterior French drains in Miami installed 2-3 feet beneath earth to move surface water away from houses. Components include perforated pipe, gravel fill, filter fabric, and outlet point."
      }
    },
    {
      "@type": "Question",
      "name": "How does a French drain work?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "French drains collect water through perforated pipe in gravel-filled trench. Water enters pipe through perforations and flows to designated outlet. Filter fabric prevents soil clogging. Proper slope ensures natural water flow. System manages water around foundations preventing damage."
      }
    },
    {
      "@type": "Question",
      "name": "When do you need a French drain?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "French drains needed to prevent foundation repairs, flooding, erosion, mold and mildew, and pest breeding grounds. Particularly valuable in Miami's tropical climate with heavy seasonal rainfall. Professional evaluation determines if French drain appropriate solution."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need permits for French drain installation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, Miami-Dade County typically requires permits for French drain installation, especially for exterior drains. Utility line verification mandatory before excavation. Professional contractors handle permit acquisition and compliance."
      }
    },
    {
      "@type": "Question",
      "name": "How long does French drain installation take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Simple exterior drains typically take 1-2 days. Complex installations take 3-5 days. Permit processing adds 1-2 weeks before installation begins. Professional contractors manage process efficiently."
      }
    },
    {
      "@type": "Question",
      "name": "What's the difference between interior and exterior French drains?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Exterior French drains installed around property perimeter, cost $10-$15 per linear foot, installed 2-3 feet deep. Interior French drains installed inside basements, cost $40-$100 per linear foot, require sump pump systems. Selection depends on specific drainage needs."
      }
    }
  ]
}

