{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do you apply for a septic permit?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Apply for septic permit by completing site evaluation and system design, compiling all required documentation including DEP4015 forms, site plan, soil evaluation report, design specifications, submitting complete application package to Miami-Dade DERM, undergoing DERM review process, addressing any deficiencies, receiving DERM approval, and obtaining additional permits from building and health departments. Professional contractors manage entire application process."
      }
    },
    {
      "@type": "Question",
      "name": "What permits do you need for a septic system?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic system installation requires mandatory prior written approval from Miami-Dade DERM Director, building department permit for installation, health department approval for operation, sewer capacity certification from DRER if applicable, and system-specific operating permits for advanced treatment systems. All permits must be obtained before installation begins."
      }
    },
    {
      "@type": "Question",
      "name": "How much do septic permits cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic permit application in Miami-Dade typically costs $500-$2,000 in permit fees depending on system type, property use, and application complexity. DERM application fees cost $500-$2,000. Total permit fees typically cost $1,300-$4,300. Additional costs for site evaluation, design, and engineering services bring total application costs to $2,300-$6,500 typically."
      }
    },
    {
      "@type": "Question",
      "name": "How long does it take to get a septic permit?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "DERM review and approval process typically takes 4-8 weeks after complete application submission, though timeline varies based on application completeness, site complexity, and DERM workload. Complete permit application process from initial submission through all approvals typically takes 6-12 weeks total. Timeline can extend if revisions are needed."
      }
    },
    {
      "@type": "Question",
      "name": "What documents are needed for septic permit?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Required documentation includes DEP4015 application forms, scaled site plan showing structures and property boundaries, soil evaluation report with percolation test results, system design specifications conforming to Chapter 62-6, proof of property ownership, professional engineer credentials, contractor licensing information, and sewer capacity certification if applicable. Documentation completeness essential for approval."
      }
    },
    {
      "@type": "Question",
      "name": "What happens after permit approval?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "After permit approval, licensed contractor begins installation following approved plans, schedules and passes inspections by Miami-Dade County Department of Health and building department, system becomes operational only after final inspection approval, system must be registered with DERM, and ongoing compliance requirements must be met including annual operating permits for certain systems."
      }
    },
    {
      "@type": "Question",
      "name": "Can permit applications be denied?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Permit applications may be denied if system design doesn't meet requirements, documentation is incomplete, site conditions prevent proper installation, setback requirements cannot be met, or environmental constraints prevent compliance. If denied, DERM provides reasons for denial, revisions may address concerns, or alternative solutions may be necessary."
      }
    }
  ]
}

