{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does septic system design cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic system design and permitting in Miami-Dade typically costs $1,500-$5,000 depending on system complexity, site conditions, and engineering requirements. Type 2 system design costs $1,500-$3,000. Type 3 costs $2,500-$4,500. Type 4 costs $4,000-$8,000. Costs include site evaluation, engineering design, site plan creation, and permit application."
      }
    },
    {
      "@type": "Question",
      "name": "What permits do you need for a septic system?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "All new or replacement systems require prior written approval from Miami-Dade DERM Director before construction. Required documentation includes scaled site plan, soil evaluation report, OSTDS design specifications conforming to Chapter 62-6, proof of property ownership, and professional engineer credentials. DERM review determines approval based on regulatory compliance."
      }
    },
    {
      "@type": "Question",
      "name": "How long does septic system permitting take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "DERM review and approval typically takes 4-8 weeks after complete application submission. Complete design and permitting process from site evaluation through approval typically takes 8-16 weeks total. Timeline varies based on application completeness, site complexity, and DERM workload. Incomplete applications or revisions extend timeline."
      }
    },
    {
      "@type": "Question",
      "name": "What are Miami-Dade requirements for septic design?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Miami-Dade County Ordinance 22-83 requires Type 2, Type 3, or Type 4 systems for new installations (Type 1 prohibited). Systems must maintain minimum 100 feet from surface water, 50 feet from property lines, and drainfield bottom must be 36 inches above high water table. Professional engineer certification required for all designs."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need an engineer to design a septic system?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, professional engineer certification is required for all septic system designs in Miami-Dade County. Engineers provide site evaluation, soil testing, system type selection, engineering calculations, site plan creation, and design specifications. Professional design ensures compliance with regulations, proper system sizing, and environmental protection."
      }
    },
    {
      "@type": "Question",
      "name": "What is the process for getting a septic permit?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Process includes site evaluation and soil testing, engineering design development, site plan creation, compilation of required documentation, DERM permit application submission, DERM review, approval or denial determination, and post-installation inspection. Professional engineers manage entire process coordinating with DERM. Process typically takes 8-16 weeks from start through approval."
      }
    },
    {
      "@type": "Question",
      "name": "What happens if my permit is denied?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "If permit is denied, DERM provides reasons for denial. Design may need revisions addressing concerns, additional site evaluation may be required, or system type may need adjustment. Revised application must be resubmitted for review. Professional engineers address denial reasons and revise design accordingly. Resubmission typically takes additional 2-4 weeks."
      }
    }
  ]
}

