{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What's the difference between septic tank cleaning and pumping?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Pumping removes liquid and solid waste that fills your tank. Cleaning goes further by removing hardened buildup, grease, and debris from tank walls, baffles, and filters using pressure washing and specialized tools. Pumping takes 1-3 hours and costs $300-$600. Cleaning takes 3-5 hours and costs $400-$800 because it includes additional steps and equipment."
      }
    },
    {
      "@type": "Question",
      "name": "How much does septic tank cleaning cost in Miami?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic tank cleaning typically costs $400-$800 for residential properties in Miami-Dade County. This is higher than pumping because cleaning requires more time, specialized equipment like pressure washers, and additional labor to remove hardened buildup from tank walls."
      }
    },
    {
      "@type": "Question",
      "name": "When do I need septic tank cleaning vs just pumping?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You need cleaning when pumping alone doesn't solve problems like odors or slow drains, when it's been 5-10 years since last cleaning, when you have a garbage disposal, or after major storms. Routine pumping every 3-5 years is usually enough if you've had cleaning within the last decade and your system is functioning normally."
      }
    },
    {
      "@type": "Question",
      "name": "How often should I clean my septic tank in Miami?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most residential systems need deep cleaning every 5-10 years, but Miami's conditions often require more frequent cleaning. Properties with garbage disposals typically need cleaning every 3-5 years. Commercial properties often need cleaning every 1-3 years depending on usage."
      }
    },
    {
      "@type": "Question",
      "name": "What's included in septic tank cleaning?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Professional cleaning includes pumping out all waste, pressure washing tank walls to remove buildup, manual scraping of stubborn deposits, cleaning and inspecting baffles and filters, removing grease and debris, inspecting components for damage, and providing a detailed service report. The process takes 3-5 hours and uses specialized equipment."
      }
    },
    {
      "@type": "Question",
      "name": "Do I need permits for septic tank cleaning?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You usually don't need a permit for routine cleaning, but your contractor must hold a valid Miami-Dade Liquid Waste Transporters permit and Florida DOH contractor registration. If cleaning reveals problems requiring repairs, those repairs may need additional permits."
      }
    },
    {
      "@type": "Question",
      "name": "How long does septic tank cleaning take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most deep cleaning takes 3-5 hours from arrival to cleanup. Simple jobs take 3-4 hours. Complex jobs with heavy buildup or difficult access can take 5-6 hours. This is longer than pumping because cleaning includes pressure washing, manual removal of buildup, and detailed component inspection."
      }
    }
  ]
}

