{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does septic tank replacement cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic tank replacement in Miami-Dade typically costs $5,000-$15,000 depending on tank size, site access, and whether drain field work is needed. Small tanks cost $5,000-$10,000. Standard tanks cost $8,000-$15,000. Large tanks cost $12,000-$20,000. Costs include tank, excavation, installation, permits, and inspection."
      }
    },
    {
      "@type": "Question",
      "name": "When do you need to replace a septic tank?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Replacement is needed when tanks have severe structural damage, extensive cracks beyond repair, collapsed sections, repeated repair failures, or when repair costs exceed 50% of replacement costs. Very old tanks (30+ years) may need replacement due to age-related deterioration. Professional inspection determines whether replacement or repair is appropriate."
      }
    },
    {
      "@type": "Question",
      "name": "How long does septic tank replacement take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Replacement timeline typically takes 1-3 weeks from permit approval through final inspection. Permit approval takes 4-8 weeks before work begins. Physical replacement takes 5-8 days. Final inspection takes 3-5 days. Total timeline from permit application to completion typically takes 6-12 weeks depending on permit approval time and site conditions."
      }
    },
    {
      "@type": "Question",
      "name": "Can you repair a septic tank instead of replacing?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Minor repairs are often sufficient for small cracks or leaks, small structural problems, or when repair costs are less than 50% of replacement. However, replacement is needed for severe damage, multiple extensive cracks, collapsed sections, repeated repair failures, or when repair costs exceed replacement value. Professional evaluation determines appropriate option."
      }
    },
    {
      "@type": "Question",
      "name": "What are signs you need septic tank replacement?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Signs include persistent leaks despite repairs, severe cracks, structural damage, repeated repair failures, tank collapse or settling, very old tanks showing deterioration, and inspection findings indicating replacement needed. Professional inspection provides definitive assessment of whether replacement is required based on damage extent."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need permits to replace a septic tank?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, complete tank replacement requires prior written approval from Miami-Dade DERM Director before replacement begins. Required documentation includes replacement plans, system design specifications, and permit application forms. New tanks must meet Type 2, Type 3, or Type 4 standards. Professional contractors handle permit applications."
      }
    },
    {
      "@type": "Question",
      "name": "What is included in septic tank replacement?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Replacement includes removal of old tank, excavation for new tank, new tank meeting current standards, tank installation and leveling, plumbing reconnection, backfilling and compaction, final inspection and approval, and system registration with DERM. Professional contractors provide comprehensive replacement services ensuring compliance with Miami-Dade requirements."
      }
    }
  ]
}

