{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does septic to sewer conversion cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic to sewer conversion in Miami-Dade typically costs $5,000-$25,000 depending on WASD connection fees, permit costs, septic abandonment, and plumbing work. WASD connection fees typically $3,000-$15,000. Permit costs total $1,200-$3,800. Septic abandonment costs $1,600-$4,600. Funding assistance programs may offset costs."
      }
    },
    {
      "@type": "Question",
      "name": "How do you convert from septic to sewer?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Conversion process includes verifying sewer lateral availability, obtaining Sewer Capacity Certification from DRER, requesting WASD Allocation Letter, obtaining plumbing permit, securing Florida DOH septic abandonment permit, getting WASD approval and paying connection fees, professionally abandoning septic tank, installing sewer connection, and completing final inspections. Process requires coordination with five agencies."
      }
    },
    {
      "@type": "Question",
      "name": "Do you have to connect to sewer if available?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, properties within WASD service areas with existing sewer laterals are required to connect to municipal sewer facilities when converting from septic systems. Connection is mandatory rather than optional where sewer service is available. Miami-Dade County Code requires connection for properties with sewer access."
      }
    },
    {
      "@type": "Question",
      "name": "What permits do you need for sewer connection?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Sewer connection requires permits from five agencies including DRER Sewer Capacity Certification Letter, DRER WASD Allocation Letter, Plumbing Permit, Florida DOH Pump-out and Abandon Permit, and WASD Approval with connection fee payment. All permits must be obtained before work begins. Professional contractors handle permit acquisition."
      }
    },
    {
      "@type": "Question",
      "name": "How long does septic to sewer conversion take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Complete conversion process typically takes 4-8 weeks from initial request through system activation. Permit acquisition takes 2-4 weeks. Construction phase takes 1-3 weeks. After connection charges paid, WASD allows 90 days before beginning process to start sewer billing, providing grace period for system verification."
      }
    },
    {
      "@type": "Question",
      "name": "What happens to the old septic tank?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Old septic tank must be properly abandoned following Florida DOH procedures. Process includes pumping out tank contents, properly abandoning tank to prevent environmental contamination, filling or removing tank per requirements, and completing site restoration. Florida DOH Pump-out and Abandon Permit required before abandonment begins."
      }
    },
    {
      "@type": "Question",
      "name": "Are funding assistance programs available?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, state and local funding initiatives provide financial assistance for septic abandonment and sewer connections. Programs allocated $800,000 for approximately 13 properties in some initiatives. Funding availability varies by program and property eligibility. Assistance programs can significantly offset connection costs."
      }
    }
  ]
}

