{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does septic site evaluation cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Site evaluation in Miami-Dade typically costs $800-$1,500 depending on property size, evaluation complexity, soil testing requirements, and professional fees. Simple residential evaluations cost $500-$1,000. Standard evaluations cost $800-$1,500. Costs include property inspection, soil testing, property assessment, and documentation."
      }
    },
    {
      "@type": "Question",
      "name": "What is a septic site evaluation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Septic site evaluation is critical preliminary assessment conducted to determine whether property is suitable for installation of onsite sewage treatment and disposal system. Evaluation involves comprehensive examination of soil characteristics, environmental conditions, and property features to ensure septic system can function safely and effectively while protecting groundwater and surface waters."
      }
    },
    {
      "@type": "Question",
      "name": "What does a site evaluation include?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Site evaluation includes property inspection and assessment, soil percolation testing to measure absorption capacity, groundwater depth evaluation, property feature identification, water well and surface water location, environmental factor assessment, and comprehensive documentation using DH4015 form. Evaluation assesses all factors affecting septic system design and installation."
      }
    },
    {
      "@type": "Question",
      "name": "Who can perform a septic site evaluation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Site evaluations must be performed by licensed engineer or other qualified professional as mandated by Florida regulations. Licensed engineers and qualified professionals must meet state licensing requirements and have experience in septic system evaluation. Professional credentials must be verified for proper assessment and documentation."
      }
    },
    {
      "@type": "Question",
      "name": "How long does site evaluation take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Site evaluation typically takes 1-2 weeks from initial inspection through completion of documentation. Property inspection takes 1-2 days. Soil testing takes 2-3 days. Documentation and report preparation takes 3-5 days. Total timeline depends on property complexity and professional workload."
      }
    },
    {
      "@type": "Question",
      "name": "What happens after site evaluation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "After site evaluation, results are used for septic system design including system type selection, placement location, sizing based on percolation rate, and treatment specifications. Evaluation results become part of permit application documentation. Professional engineer uses evaluation results to design system meeting all requirements."
      }
    },
    {
      "@type": "Question",
      "name": "Can a property fail site evaluation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Site evaluation may determine property is not suitable for septic system installation if soil conditions are inadequate, groundwater is too shallow, setbacks cannot be met, or environmental constraints prevent installation. In such cases, alternatives may be available including advanced treatment systems, holding tanks, or connection to municipal sewer if available."
      }
    }
  ]
}

