  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does stormwater runoff control cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Stormwater runoff control in Miami typically costs $3,000-$20,000 for property-level systems depending on size, BMP types, pollution control devices, and compliance requirements. Basic systems cost $3,000-$8,000. Standard systems cost $8,000-$15,000. Comprehensive systems cost $15,000-$30,000."
      }
    },
    {
      "@type": "Question",
      "name": "What is stormwater runoff control?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Stormwater runoff control manages rain and tidal water flowing over surfaces collecting pollutants before entering stormwater systems. Control serves three primary objectives: draining stormwater quickly preventing flooding, cleaning contaminants before discharge, and managing stormwater to recharge groundwater supplies. The first inch of runoff carries 90% of pollution making treatment critical."
      }
    },
    {
      "@type": "Question",
      "name": "Why is stormwater runoff control important?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Stormwater runoff control important for preventing contamination of waterways, protecting Biscayne Bay water quality, reducing pollutants entering ecosystems, draining stormwater quickly preventing flooding, cleaning contaminants before discharge, managing stormwater for groundwater recharge, and meeting NPDES permit requirements and Miami-Dade County ordinances."
      }
    },
    {
      "@type": "Question",
      "name": "What are stormwater best management practices?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Best management practices include pollution reduction through public education and good housekeeping, surface drainage and flood protection, erosion and sedimentation control, treatment BMPs like permeable surfaces and vegetated areas, and treatment of first inch of runoff addressing 90% of pollution."
      }
    },
    {
      "@type": "Question",
      "name": "How do you control stormwater runoff?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Control stormwater runoff through structural BMPs like permeable pavements and detention ponds, vegetated BMPs like rain gardens and bioswales, pollution control devices like oil separators and sediment filters, source control through public education, and treatment of first flush runoff. Professional evaluation determines best approach."
      }
    },
    {
      "@type": "Question",
      "name": "What maintenance do stormwater control systems need?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Maintenance requirements include regular cleaning of BMPs and treatment areas, removing accumulated debris, inspection of system components and pollution control devices, cleaning pollution control devices, and vegetation management maintaining vegetated BMPs. Regular maintenance ensures continued effectiveness."
      }
    },
    {
      "@type": "Question",
      "name": "What are NPDES permit requirements?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Miami-Dade County operates under NPDES permit covering county and over 30 local municipalities, establishing water quality standards and regulating discharge from municipal stormwater systems. NPDES requires operators to develop best management practices improving quality of stormwater discharges. Compliance essential for legal operation."
      }
    }
  ]
}

