{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much do yard drainage solutions cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yard drainage solutions in Miami typically cost $2,500-$7,000 for standard installations, with costs varying based on system type, property size, excavation complexity, and Miami's limestone bedrock. French drains cost $10-$50 per linear foot. Catch basins cost $200-$5,000 each. Complex installations can exceed $15,000."
      }
    },
    {
      "@type": "Question",
      "name": "What are the best yard drainage solutions?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Best yard drainage solutions for Miami include French drains installed 2-3 feet deep for high water table, catch basins managing heavy tropical rainfall, trench drains for driveways and patios, dry wells for gradual water release, and underground downspout extensions preventing foundation damage. System selection depends on specific problems."
      }
    },
    {
      "@type": "Question",
      "name": "How do you fix yard drainage problems?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fix yard drainage problems through professional assessment identifying specific issues, system design appropriate for Miami conditions, proper installation accounting for high water table and limestone, compliance with Miami-Dade regulations, and regular maintenance ensuring continued effectiveness."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need permits for yard drainage?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, Miami-Dade County requires permits for yard drainage modifications, especially systems connecting to storm drains or affecting property drainage patterns. Permit process ensures compliance. Utility line verification mandatory before excavation. Professional contractors handle permit acquisition."
      }
    },
    {
      "@type": "Question",
      "name": "What causes yard drainage problems?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yard drainage problems caused by high water table keeping soil saturated, heavy tropical rainfall overwhelming natural drainage, poor property grading directing water toward structures, clay or compacted soil preventing water absorption, and inadequate drainage systems for property needs."
      }
    },
    {
      "@type": "Question",
      "name": "How long does yard drainage installation take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yard drainage installation typically takes 2-5 days for standard systems, longer for complex installations with extensive excavation. Permit processing adds 1-2 weeks before installation begins. Timeline varies based on system scope and limestone excavation challenges."
      }
    },
    {
      "@type": "Question",
      "name": "What maintenance do yard drainage systems require?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yard drainage systems require regular cleaning every few years costing $300-$700, debris removal preventing blockages, inspection for erosion or settling, more frequent maintenance during hurricane season, and occasional repairs costing $100-$250 minimum. Regular maintenance ensures continued effectiveness."
      }
    }
  ]
}

